const int POT = A0;
const int LED = 9;

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int adc = analogRead(POT);                // 0–1023
  int pwm = map(adc, 0, 1023, 0, 255);      // skala ke 0–255
  analogWrite(LED, pwm);

  float tegangan = adc * (5.0 / 1023.0);
  Serial.print("ADC: ");
  Serial.print(adc);
  Serial.print(" | Tegangan: ");
  Serial.print(tegangan, 2);
  Serial.println(" V");
  delay(100);
}

const int TRIG = 9;
const int ECHO = 10;

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
}

void loop() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);

  long durasi = pulseIn(ECHO, HIGH, 30000);  // timeout 30 ms
  float jarak = durasi * 0.0343 / 2.0;

  Serial.print("Jarak: ");
  Serial.print(jarak);
  Serial.println(" cm");
  delay(300);
}

#include <Wire.h>
#include <DHT.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define DHTPIN 2
#define DHTTYPE DHT11
#define MQ135PIN A0

DHT dht(DHTPIN, DHTTYPE);
Adafruit_SSD1306 display(128, 64, &Wire, -1);

const char* klasifikasi(int adc) {
  if (adc < 181) return "BAIK";
  else if (adc < 225) return "SEDANG";
  else if (adc < 300) return "BURUK";
  else return "SANGAT BURUK";
}

void setup() {
  Serial.begin(9600);
  dht.begin();
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println(F("OLED tidak terdeteksi"));
    while (true);
  }
  display.setTextColor(WHITE);
}

void loop() {
  int gas = analogRead(MQ135PIN);
  float h = dht.readHumidity();
  float t = dht.readTemperature();

  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.println(F("Monitor Lingkungan"));
  display.setCursor(0, 16);
  display.print(F("Udara: "));
  display.println(klasifikasi(gas));

  if (isnan(h) || isnan(t)) {
    display.setCursor(0, 40);
    display.println(F("DHT gagal dibaca"));
  } else {
    display.setCursor(0, 40);
    display.print(F("Suhu : "));
    display.print(t, 1);
    display.println(F(" C"));
    display.setCursor(0, 52);
    display.print(F("RH   : "));
    display.print(h, 0);
    display.println(F(" %"));
  }
  display.display();
  delay(2000);  // DHT11 maksimal 1 pembacaan per detik
}
